"""Reconstruct the spike shapes of Supplementary Fig. 3a-b from the vector figures generated by notebooks/1_results/supp_fig3_AB_plotSpikes.ipynb
(git commit 546e1cb: figures/6_supp/fig3/fig3A_spikes_ex_mtypes.svg and fig3B_spikes_inh_mtypes.svg).

usage (from the repository root): python src/pipes/validation/spike_shapes/extract_spike_shapes_from_svg.py
"""
import re, numpy as np, pandas as pd, sys
def parse(path, panel, cell_class, colors):
    s = open(path).read()
    axes = re.split(r'<g id="axes_\d+">', s)[1:]
    rows = []
    for a in axes:
        # axes box
        d0 = re.search(r'<g id="patch_\d+">\s*<path d="([^"]*)"', a).group(1)
        nums = [list(map(float, l.split()[1:3])) for l in d0.strip().split("\n") if l[0] in "ML"]
        L, R, T = min(n[0] for n in nums), max(n[0] for n in nums), min(n[1] for n in nums)
        # y ticks: pixel y and label
        ticks = []
        for g in re.findall(r'<g id="ytick_\d+">(.*?)</g>\s*</g>\s*</g>', a, flags=re.S):
            yp = float(re.search(r'<use xlink:href="#\w+" x="[\d.\-]+" y="([\d.\-]+)"', g).group(1))
            lab = re.search(r'<!-- (.*?) -->', g).group(1).replace("−", "-")
            ticks.append((yp, float(lab)))
        (y0, v0), (y1, v1) = ticks[0], ticks[-1]
        slope = (v1 - v0) / (y1 - y0)
        # lines
        lines = re.findall(r'<g id="line2d_\d+">\s*<path d="([^"]*)"[^>]*stroke: (#[0-9a-f]{6})', a, flags=re.S)
        lines = [(d, c) for d, c in lines if c in colors]
        title = re.findall(r'<!-- ([^>]*?) -->\s*<g transform="translate\([\d. ]+\) scale\(0.072', a)
        title = title[-1] if title else None
        for d, c in lines:
            pts = np.array([[float(v) for v in p.split()[1:3]] for p in d.strip().split("\n")])
            t = (pts[:, 0] - L) / (R - L)         # fraction of axes width
            t_ms = -1.0 + (pts[:, 0] - (L + (R - L) * 0.05 * 3.975 / 4.3736)) / ((R - L) * 3.975 / 4.3736) * 3.975
            v = v0 + (pts[:, 1] - y0) * slope
            rows.append(dict(panel=panel, axes_left_px=L, axes_top_px=T, mtype=title, electrode=colors[c], t_ms=t_ms, v_mV=v, ticks=ticks))
    return rows
if __name__ == "__main__":
    import os
    ex = parse("figures/6_supp/fig3/fig3A_spikes_ex_mtypes.svg", "a", None, {"#d62728": "above", "#ff7f0e": "below"})
    inh = parse("figures/6_supp/fig3/fig3B_spikes_inh_mtypes.svg", "b", None, {"#1f77b4": "above", "#9467bd": "below"})
    grid = -1 + 0.025 * np.arange(160)        # 40 kHz, 1 ms before to 3 ms after the spike peak
    out = []
    for rows, cls in ((ex, "EXC"), (inh, "INH")):
        lefts = sorted(set(round(r["axes_left_px"]) for r in rows))
        tops = sorted(set(round(r["axes_top_px"]) for r in rows))
        for r in rows:
            o = np.argsort(r["t_ms"])
            v = np.interp(grid, r["t_ms"][o], r["v_mV"][o])
            out.append(pd.DataFrame(dict(panel=r["panel"], synapse_class=cls, column=lefts.index(round(r["axes_left_px"])) + 1,
                                         row=tops.index(round(r["axes_top_px"])) + 1, mtype=r["mtype"], electrode=r["electrode"], time_ms=grid, voltage_mV=v)))
    pd.concat(out, ignore_index=True).to_csv("dataset/01_intermediate/supplementary/spike_shapes/spike_shapes_above_below_somata.csv", index=False)
